std::vector<std::vector<u8>> pack_state(u32 epoch, const std::vector<LampRec>& lamps, const std::vector<PlankRec>& planks, const std::vector<MarkRec>& marks) {
  // a part: kind, epoch, flags (1 first, 2 last), then three counted lists (u16 each); the records
  // are dealt out in their order - lamps, planks, marks - a part taking what fits
  std::vector<std::vector<u8>> out;
  std::size_t li = 0, pi = 0, mi = 0;
  do { ::sc::lowered::tick();
    std::size_t room = kStateBytes - 12;
    const std::size_t nl = std::min(lamps.size() - li, ::sc::lowered::quot(room, kLampBytes));
    room -= nl * kLampBytes;
    const std::size_t np = li + nl == lamps.size() ? std::min(planks.size() - pi, ::sc::lowered::quot(room, kPlankBytes)) : 0;
    room -= np * kPlankBytes;
    const std::size_t nm = li + nl == lamps.size() && pi + np == planks.size() ? std::min(marks.size() - mi, ::sc::lowered::quot(room, kMarkBytes)) : 0;
    const bool last = li + nl == lamps.size() && pi + np == planks.size() && mi + nm == marks.size();
    Out o;
    o.put(static_cast<u8>(Kind::state)).put(epoch).put(static_cast<u8>((out.empty() ? 1 : 0) | (last ? 2 : 0)));
    o.put(static_cast<u16>(nl));
    for (std::size_t i = li; (::sc::lowered::tick(), i < li + nl); ++i) o.put(::sc::converted::at(lamps, i).key).put(::sc::converted::at(lamps, i).state);
    o.put(static_cast<u16>(np));
    for (std::size_t i = pi; (::sc::lowered::tick(), i < pi + np); ++i) o.put(::sc::converted::at(planks, i).key).put(::sc::converted::at(planks, i).door).put(::sc::converted::at(planks, i).doors).put(::sc::converted::at(planks, i).planks);
    o.put(static_cast<u16>(nm));
    for (std::size_t i = mi; (::sc::lowered::tick(), i < mi + nm); ++i) o.put(::sc::converted::at(marks, i).at).put(::sc::converted::at(marks, i).radius).put(::sc::converted::at(marks, i).strength);
    out.push_back(std::move(o.b));
    li += nl;
    pi += np;
    mi += nm;
  } while (li < lamps.size() || pi < planks.size() || mi < marks.size());
  return out;
}

bool unpack_state(const std::vector<u8>& blob, State& s) {
  In in{blob};
  s = State{};
  if (in.get<u8>() != static_cast<u8>(Kind::state)) return false;
  s.epoch = in.get<u32>();
  const u8 flags = in.get<u8>();
  s.first = flags & 1;
  s.last = flags & 2;
  const u16 nl = in.get<u16>();
  for (u16 i = 0; i < nl && in.ok; ++i) { ::sc::lowered::tick();
    LampRec r;
    r.key = in.get<i64>();
    r.state = in.get<u8>();
    if (!in.ok || !lamp_ok(r)) return false;
    s.lamps.push_back(r);
  }
  const u16 np = in.get<u16>();
  for (u16 i = 0; i < np && in.ok; ++i) { ::sc::lowered::tick();
    PlankRec r;
    r.key = in.get<i64>();
    r.door = in.get<u8>();
    r.doors = in.get<u8>();
    r.planks = in.get<u8>();
    if (!in.ok || !plank_ok(r)) return false;
    s.planks.push_back(r);
  }
  const u16 nm = in.get<u16>();
  for (u16 i = 0; i < nm && in.ok; ++i) { ::sc::lowered::tick();
    MarkRec m;
    m.at = in.get<Vec3>();
    m.radius = in.get<f32>();
    m.strength = in.get<f32>();
    if (!in.ok || !mark_ok(m)) return false;
    s.marks.push_back(m);
  }
  return in.done();
}

